 saveEvents.Clear();picker.Selected=Path.Combine(output,"accepted.xml");File.Delete(picker.Selected);saveEditor.State.Invoke(saveEditor.State.Find("SaveCalibPath")!);Console.WriteLine("SAVE-DIAG "+JsonSerializer.Serialize(new{exists=File.Exists(picker.Selected),path=Node().Parameters["CalibPathName"].GetString(),events=saveEvents,notice=notice.Last,statePath=saveEditor.State.Find("CalibPathName")!.Value,effectivePath=context.ReadEffectiveParameters?.Invoke()?["CalibPathName"].GetString(),mode=Node().Parameters["InputType"].GetInt32(),scopeDisplay=plugin.LastDisplay(Node(),doc.BaseDirectory,context.Scope) is not null,diagnostics=saveEditor.State.Diagnostics}));Check(File.Exists(picker.Selected)&&Node().Parameters["CalibPathName"].GetString()==picker.Selected,"real paired image save exports and reads back path");Check(picker.History==1&&saveEvents.SequenceEqual(new[]{"select","history","notify:Success"}),"source save export/readback precedes history then success notification");}
