 sealed class SavePicker(List<string> events):IToolConfigurationSaveFileService{public string Selected="";public int History;public ConfigurationFileSelection SelectSave(Window? owner,ConfigurationSaveFileRequest request){events.Add("select");return new(ConfigurationFileStatus.Selected,[Selected]);}public ConfigurationFileHistoryResult Remember(string moduleKey,string path){events.Add("history");History++;return new(true,Path.GetDirectoryName(path));}}
